# Error codes

Every code cartctl can print, in the format `error <code>: <message>`.

| code | message | when |
|---|---|---|
| E_UNKNOWN_SKU | unknown sku | the sku is not in the catalogue |
| E_EMPTY_CART | cart is empty | checkout was asked for an empty cart |
| E_USAGE | usage: cartctl add <sku> <qty> | the command line could not be parsed |
=== errors.ts
// User-facing failures. See CONTRIBUTING.md, "Errors".

export const ERROR_CODES = {
  E_UNKNOWN_SKU: "unknown sku",
  E_EMPTY_CART: "cart is empty",
  E_USAGE: "usage: cartctl add <sku> <qty>",
} as const;

export type ErrorCode = keyof typeof ERROR_CODES;

export class CliError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.name = "CliError";
    this.code = code;
  }
}

export function fail(code: string, message?: string): never {
  if (!(code in ERROR_CODES)) throw new Error(`unregistered error code ${code}`);
  throw new CliError(code, message ?? ERROR_CODES[code as ErrorCode]);
}
=== add.ts
import type { Cart } from "../cart.ts";
import { CATALOGUE } from "../catalogue.ts";
import { fail } from "../errors.ts";

// Add qty of sku to the cart, merging with an existing line for the same sku.
export function addItem(cart: Cart, sku: string, qty: number): Cart {
  if (!(sku in CATALOGUE)) fail("E_UNKNOWN_SKU", `unknown sku ${sku}`);
  const lines = cart.lines.map((l) => ({ ...l }));
  const existing = lines.find((l) => l.sku === sku);
  if (existing) existing.qty += qty;
  else lines.push({ sku, qty });
  return { lines };
}
=== cart.ts
export interface Line {
  sku: string;
  qty: number;
}

export interface Cart {
  lines: Line[];
}

export function emptyCart(): Cart {
  return { lines: [] };
}
=== cli.ts
import { emptyCart } from "./cart.ts";
import { addItem } from "./commands/add.ts";
import { totalCents } from "./commands/checkout.ts";
import { CliError, fail } from "./errors.ts";

export function run(argv: string[]): number {
  try {
    if (argv[0] !== "add" || argv.length !== 3) fail("E_USAGE");
    const cart = addItem(emptyCart(), argv[1], Number(argv[2]));
    process.stdout.write(`${cart.lines.length} line(s), total ${totalCents(cart)}\n`);
    return 0;
  } catch (e) {
    if (e instanceof CliError) {
      process.stderr.write(`error ${e.code}: ${e.message}\n`);
      return 2;
    }
    process.stderr.write(`${(e as Error).stack ?? e}\n`);
    return 70;
  }
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(run(process.argv.slice(2)));
=== checkout.ts
import type { Cart } from "../cart.ts";
import { CATALOGUE } from "../catalogue.ts";
import { fail } from "../errors.ts";

export function totalCents(cart: Cart): number {
  if (cart.lines.length === 0) fail("E_EMPTY_CART");
  return cart.lines.reduce((sum, l) => sum + l.qty * CATALOGUE[l.sku].priceCents, 0);
}

